arguments.file_text:
@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Kanban Board</h2>

@if (isLoading)
{
    <p class="board-loading">Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <div class="board-error">
        <p>@errorMessage</p>
        <button @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <BoardSummary Tasks="allTasks" />
    <BoardSearch OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Tasks="GetFilteredTasks("To Do")"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="@(task => MoveTaskAsync(task, "In Progress"))"
                      OnAddTask="@(args => AddTaskAsync(args, "To Do"))" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="GetFilteredTasks("In Progress")"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="@(task => MoveTaskAsync(task, "To Do"))"
                      OnMoveRight="@(task => MoveTaskAsync(task, "Done"))"
                      OnAddTask="@(args => AddTaskAsync(args, "In Progress"))" />

        <KanbanColumn ColumnName="Done"
                      Tasks="GetFilteredTasks("Done")"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="@(task => MoveTaskAsync(task, "In Progress"))"
                      OnAddTask="@(args => AddTaskAsync(args, "Done"))" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }

        return tasks.ToList();
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private async Task MoveTaskAsync(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            allTasks = allTasks.Select(t => t.Id == task.Id ? t with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task AddTaskAsync((string Title, string Assignee, string Priority, DateTime DueDate) args, string status)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(args.Title, args.Assignee, args.Priority, args.DueDate);
            allTasks.Add(created with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

/* ── Summary stats bar ── */
.board-summary {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
}

.stat {
    text-align: center;
}

.stat-label {
    display: block;
    font-size: 0.75rem;
    color: #6c757d;
    text-transform: uppercase;
}

.stat-value {
    display: block;
    font-size: 1.5rem;
    font-weight: 700;
}

.stat-overdue .stat-value {
    color: #dc3545;
}

/* ── Search bar ── */
.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
}

/* ── Board layout ── */
.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 0.75rem;
    min-width: 0;
}

.column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.column-count {
    background: #dee2e6;
    border-radius: 999px;
    padding: 0.15rem 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

/* ── Task card ── */
.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.4rem;
}

.task-title {
    font-weight: 600;
    font-size: 0.9rem;
}

.priority-badge {
    font-size: 0.7rem;
    padding: 0.15rem 0.5rem;
    border-radius: 999px;
    font-weight: 600;
    text-transform: uppercase;
}

.priority-high {
    background: #dc3545;
    color: #fff;
}

.priority-medium {
    background: #ffc107;
    color: #212529;
}

.priority-low {
    background: #28a745;
    color: #fff;
}

.task-meta {
    display: flex;
    justify-content: space-between;
    font-size: 0.8rem;
    color: #6c757d;
    margin-bottom: 0.5rem;
}

.task-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

/* ── Add task ── */
.btn-add-task {
    width: 100%;
    margin-top: 0.5rem;
    padding: 0.5rem;
    border: 2px dashed #ced4da;
    border-radius: 6px;
    background: transparent;
    color: #6c757d;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-add-task:hover {
    border-color: #868e96;
    color: #495057;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    margin-top: 0.5rem;
    padding: 0.75rem;
    background: #fff;
    border: 1px solid #ced4da;
    border-radius: 6px;
}

.add-task-form input,
.add-task-form select {
    padding: 0.35rem 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.85rem;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    padding: 0.35rem 0.75rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-save:disabled {
    opacity: 0.6;
}

.btn-cancel {
    padding: 0.35rem 0.75rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.form-error {
    color: #dc3545;
    font-size: 0.8rem;
    margin: 0;
}

/* ── Loading / Error states ── */
.board-loading {
    text-align: center;
    color: #6c757d;
    padding: 2rem;
}

.board-error {
    text-align: center;
    padding: 2rem;
    color: #dc3545;
}

.board-error button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    border: 1px solid #dc3545;
    background: #fff;
    color: #dc3545;
    border-radius: 4px;
    cursor: pointer;
}

